from pathlib import Path

p = Path('tools/patch_beta40.py')
s = p.read_text()

old = '''rep('f << \"Built-in CPU/RAM/combined/GPU validation completed.\\\\n\";',\n    'f << \"Built-in CPU-memtester, RAM-rail and combined validation completed.\\\\n\";',\n    'results validation summary')\n\np.write_text(s)'''
new = '''# Keep beta39's Part-1 wording; beta40's detailed flow is documented in the\n# release notes and visible on each test page.\n\n# Show a liability / risk disclaimer on every launch, after the updater and\n# before any hardware detection, tuning or stress-test workflow begins.\ndisclaimer_anchor = ''' + "'''" + '''    if (updater::startupCheckAndPrompt(pad, argc, argv)) {\n        consoleExit(nullptr);\n        return 0;\n    }\n\n    ensureDir();''' + "'''" + '''\ndisclaimer_replacement = ''' + "'''" + '''    if (updater::startupCheckAndPrompt(pad, argc, argv)) {\n        consoleExit(nullptr);\n        return 0;\n    }\n\n    bool riskAccepted = false;\n    while (appletMainLoop() && !riskAccepted) {\n        padUpdate(&pad);\n        const u64 k = padGetButtonsDown(&pad);\n        consoleClear();\n        std::printf(\"\\x1b[1;1H\\x1b[31mHOC Undervolting Wizard - WARNING\\x1b[0m\\n\");\n        std::printf(\"------------------------------------------------------------\\n\\n\");\n        std::printf(\"\\x1b[1mUSE AT YOUR OWN RISK\\x1b[0m\\n\\n\");\n        std::printf(\"This Wizard changes CPU/RAM voltage settings and runs\\n\");\n        std::printf(\"stability tests. Unstable settings can cause crashes,\\n\");\n        std::printf(\"boot failures, data/save corruption or data loss.\\n\\n\");\n        std::printf(\"In extreme cases, hardware damage may also be possible.\\n\\n\");\n        std::printf(\"The author and contributors provide no warranty and accept\\n\");\n        std::printf(\"no liability for data loss, software damage, hardware\\n\");\n        std::printf(\"damage or any other consequences of using this Wizard.\\n\\n\");\n        std::printf(\"By continuing, you accept all risk and responsibility.\\n\\n\");\n        std::printf(\"[A] I understand - Continue\\n\");\n        std::printf(\"[B] Exit\\n\");\n        consoleUpdate(nullptr);\n\n        if (k & HidNpadButton_A) riskAccepted = true;\n        else if (k & HidNpadButton_B) {\n            consoleExit(nullptr);\n            return 0;\n        }\n        svcSleepThread(20'000'000);\n    }\n\n    if (!riskAccepted) {\n        consoleExit(nullptr);\n        return 0;\n    }\n\n    ensureDir();''' + "'''" + '''\nrep(disclaimer_anchor, disclaimer_replacement, 'startup disclaimer')\n\np.write_text(s)'''

if old not in s:
    raise SystemExit('old beta40 results-summary block not found')
s = s.replace(old, new, 1)
p.write_text(s)
